package main

import (
	"fmt"
	"math"
)

func main() {
	var n int
	fmt.Scan(&n)

	// Find the largest divisor a such that a <= b and a*b = n
	// We want a <= b, so a <= sqrt(n)
	// We want to minimize b - a, which means a should be as large as possible (closest to sqrt(n))

	sqrtN := int(math.Sqrt(float64(n)))

	// Start from sqrtN and go down to find the largest divisor
	for a := sqrtN; a >= 1; a-- {
		if n%a == 0 {
			b := n / a
			fmt.Printf("%d %d\n", a, b)
			return
		}
	}
}
