package main

import (
	"fmt"
	"math"
)

func main() {
	var n int
	fmt.Scan(&n)

	// Find the largest divisor a <= sqrt(n)
	// Then b = n / a, and a <= b
	// We want to minimize b - a

	bestA := 1
	bestB := n

	for i := int(math.Sqrt(float64(n))); i >= 1; i-- {
		if n%i == 0 {
			a := i
			b := n / i
			if a <= b {
				// This is a valid pair, and since we're going from sqrt(n) downwards,
				// the first one we find will have the smallest difference
				bestA = a
				bestB = b
				break
			}
		}
	}

	fmt.Println(bestA, bestB)
}
